def recall_at_k(retrieved: list[list[str]], relevant: list[set[str]], k: int) -> float:
    if not retrieved:
        return 0.0
    hits = sum(1 for docs, rel in zip(retrieved, relevant) if set(docs[:k]) & rel)
    return hits / len(retrieved)

def pairwise_judge(question, a, b, judge) -> str:
    v1 = judge(question, a, b)
    v2 = judge(question, b, a)
    a_wins_1 = v1 == 'first'
    a_wins_2 = v2 == 'second'
    if a_wins_1 and a_wins_2:
        return 'a'
    if not a_wins_1 and not a_wins_2:
        return 'b'
    return 'tie'

